# Load the new demos if available
import os, glob, re

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

print("Available keys:", list(G.keys()))

if 'Demo pair 3 input' in G:
    print("\n=== DEMO 3 INPUT ===")
    print(f"{len(G['Demo pair 3 input'])}x{len(G['Demo pair 3 input'][0])}")
    for r in range(5):
        print(G['Demo pair 3 input'][r])

    if 'Demo pair 3 output' in G:
        print("\n=== DEMO 3 OUTPUT ===")
        print(f"{len(G['Demo pair 3 output'])}x{len(G['Demo pair 3 output'][0])}")
        for r in range(5):
            print(G['Demo pair 3 output'][r])

elif len(G) == 2:
    print("Only 2 demos loaded (no Demo 3)")

# Check exact right half counts for Demo 1
demo1_in = G['Demo pair 1 input']
divider_col = 11
width = 11

right_counts = {}
for r in range(3):
    for c in range(divider_col+1, divider_col+1+width):
        val = demo1_in[r][c]
        right_counts[val] = right_counts.get(val, 0) + 1

print(f"Right half counts: {right_counts}")
print(f"Total: {sum(right_counts.values())}")

# For Test Input
test_in = G['Test input']
test_width = 13
test_left = {}
test_right = {}

for r in range(len(test_in)):
    for c in range(test_width):
        test_left[test_in[r][c]] = test_left.get(test_in[r][c], 0) + 1

    for c in range(divider_col+1, divider_col+1+test_width):
        test_right[test_in[r][c]] = test_right.get(test_in[r][c], 0) + 1

print(f"\nTest Input Left: {sorted(test_left.items(), key=lambda x: -x[1])}")
print(f"Test Input Right: {sorted(test_right.items(), key=lambda x: -x: -x[1])}")

# What if DIFF output takes the MOST FREQUENT NON-BG value from RIGHT half?
demo1_nb_right = max((k for k,v in right_counts.items() if k != 4), key=lambda k: right_counts[k])
print(f"\nMost freq non-bg in Demo 1 right: {demo1_nb_right} with count {right_counts[demo1_nb_right]}")

